use semio_framework_job::{OriginalJobFixtureCaller,OperationId,Generation,InteractiveStage};
use semio_framework_job_worker_authority::{BatchDriveConfig};
#[global_allocator]
static HEAP:semio_framework_trace::HeapWitness=semio_framework_trace::HeapWitness;
#[test]
fn original_compute_parameters_phase_the_actual_source_alias_without_trace_authority(){let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let stock=semio_framework_value::RetainedCloneGrant{maximum_items:100000,maximum_copy_bytes:1048576,maximum_capacity_bytes:1048576,maximum_release_bytes:1048576,maximum_depth:128};let policy=semio_framework_value::RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:65536,maximum_release_bytes:65536,maximum_depth:64};let config=BatchDriveConfig{retained:policy,site:"original.compute.fixture",stage:InteractiveStage::UserVisibleSimStep,fuel_per_step:17,step_budget_us:1000};let mut caller=OriginalJobFixtureCaller::admit(OperationId(law["original"]["operation"].as_u64().unwrap()),Generation(law["original"]["generation"].as_u64().unwrap()),stock,semio_framework_job::logical_now_us,1000000,1000000);let mut owner=caller.turn(policy,|cx|ComputeJobParamsPreparation::admit(config,cx)).unwrap().unwrap();assert_eq!(caller.receipt().copied_items,1);let mut callers=[Some(caller),None];let before=callers[0].as_mut().unwrap().turn(policy,|cx|{let pointer=cx.original_source_parent()?as*const _ as usize;cx.consume_retained(semio_framework_value::RetainedCloneProgress{copied_items:1,copied_bytes:std::mem::size_of::<OriginalJobFixtureCaller>(),..Default::default()})?;cx.consume_fuel(1);Ok(pointer)}).unwrap();let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||callers[1]=callers[0].take());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let after=callers[1].as_mut().unwrap().turn(policy,|cx|Ok(cx.original_source_parent()?as*const _ as usize)).unwrap();assert_ne!(before,after);let caller=callers[1].as_mut().unwrap();let mut params=None;let zero=semio_framework_value::RetainedCloneGrant{maximum_items:0,..policy};let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn(zero,|cx|owner.advance(&mut params,cx)));assert!(!result.unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(params.is_none());let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn(policy,|cx|owner.advance(&mut params,cx)));assert!(!result.unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(caller.receipt().copied_items,1);assert!(params.is_none());let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn(policy,|cx|owner.advance(&mut params,cx)));assert!(result.unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(caller.receipt().copied_items,1);let params=params.take().unwrap();assert_eq!((params.operation.0,params.generation.0),(71,3));assert!(params.cancel.is_same_node(caller.cancel()));assert!(std::ptr::fn_addr_eq(params.now_us,semio_framework_job::logical_now_us as fn()->Option<u64>));assert!(owner.terminal_is_empty());drop(owner);caller.return_alias(params.cancel,policy);let caller=callers[1].take().unwrap();caller.retire(stock);eprintln!("[DEBUG] Compute original71/3, source clock/cancellation witness, metadata→alias→publish eachitem1/copy4096, zero denial0heap, complete original alias retirement; diagnostictrace99/gen8 unused; paid caller wrapper moved same source roots, allocator0/0");}
